/* generic left fold over an array; acc is mutated in place */
void *fold(const void *items, size_t n, size_t esz,
           void *acc, void (*combine)(void *, const void *)) {
    const unsigned char *p = items;
    for (size_t i = 0; i < n; i++, p += esz)
        combine(acc, p);
    return acc;
}
/* linked list instead walks the nodes: for (n = head; n; n = n->next) combine(acc, n); */

