typedef enum { TAG_NUM, TAG_ADD, TAG_MUL } Tag;
typedef struct Node {
    Tag tag;
    union { double num; struct { struct Node *l, *r; } bin; } u;
} Node;

static double eval(const Node *n) {            /* the algebra, inline in the recursion */
    switch (n->tag) {
    case TAG_NUM: return n->u.num;
    case TAG_ADD: return eval(n->u.bin.l) + eval(n->u.bin.r);
    case TAG_MUL: return eval(n->u.bin.l) * eval(n->u.bin.r);
    }
    abort();                                    /* C never checks exhaustiveness */
}
